const body = $input.first().json.body;
const sha = body.after || '';
const repo = body.repository?.full_name || '';
const cloneUrl = body.repository?.clone_url || '';

// Collect all changed files across commits
const changedFiles = [];
for (const commit of (body.commits || [])) {
  for (const f of [...(commit.added || []), ...(commit.modified || [])]) {
    if ((f.endsWith('.yaml') || f.endsWith('.yml')) &&
        /^(olympus|apps|infrastructure|databases|monitoring)\//.test(f)) {
      if (!changedFiles.includes(f)) changedFiles.push(f);
    }
  }
}

if (changedFiles.length === 0) {
  return [{ json: { skip: true, sha, repo, reason: 'No relevant YAML files changed' } }];
}

return [{ json: { skip: false, sha, repo, clone_url: cloneUrl, yaml_files: changedFiles } }];

const { sha, repo, yaml_files } = $input.first().json;
const token = process.env.GITEA_API_TOKEN || '';
const headers = { 'Authorization': 'token ' + token };

let combinedContent = '';
for (const filePath of yaml_files.slice(0, 10)) {
  try {
    const resp = await fetch(
      'http://gitea-gitea-web.apps.svc.cluster.local:3000/api/v1/repos/' + repo + '/raw/' + filePath + '?ref=' + sha,
      { headers }
    );
    const content = await resp.text();
    combinedContent += '\n### ' + filePath + '\n```yaml\n' + content.substring(0, 3000) + '\n```\n';
  } catch (e) {
    combinedContent += '\n### ' + filePath + '\n[Error fetching: ' + e.message + ']\n';
  }
}

return [{ json: { sha, repo, yaml_files, combined_yaml: combinedContent } }];
